import{_ as t,o,c,a5 as r}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"IDEA配置Maven","description":"","frontmatter":{"title":"IDEA配置Maven","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","构建运维","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第七部分：构建与运维/01-Maven/IDEA配置Maven.md","filePath":"posts/java快速入门/第七部分：构建与运维/01-Maven/IDEA配置Maven.md"}'),l={name:"posts/java快速入门/第七部分：构建与运维/01-Maven/IDEA配置Maven.md"};function a(d,e,n,p,g,s){return o(),c("div",null,[...e[0]||(e[0]=[r(`<div><p><code>Idea</code> 自带了<code>apache maven</code>，默认使用的是内置<code>maven</code>，所以我们可以配置全局<code>setting</code>，来调整一下配置，比如远程仓库地址，本地编译环境变量等。</p><p><code>1.</code>打开<code>Settings,</code>在输入框输入<code>maven</code>，如图</p><p><code>2.</code>如果本地设置了<code>MAVEN_OPTS</code> 系统环境变量，这个步骤可以忽略。</p><p><code>3.</code>如果配置了本地<code>apache-maven setting.xml</code> 中的软件源，这步骤可以忽略。</p><p><strong>利用</strong><code>maven</code><strong>骨架建立一个</strong><code>webapp</code> 选择<code>create new project-Maven-Create from archetype</code>。找到<code>maven-archetype-webapp</code>这个骨架，然后<code>next</code>。</p><p>输入<code>GroupId</code>和<code>ArtifactId</code>后下一步。</p><p>填写本地的<code>maven</code>环境，这里可以选择自己本地的环境，也可以用<code>idea</code>自带的<code>maven3.0.5</code>。配置相应的配置文件，<code>idea</code>自带的<code>maven</code>是没有配置文件的，需要单独配置的可以在相应的目录中添加<code>setting.xml</code>文件，例如需要配置<code>jdk</code>版本或者<code>maven mirror</code>的。</p><p>由于<code>maven</code>骨架和一些<code>jar</code>需要去<code>maven</code>的仓库下载，所以创建项目的时候速度会非常慢（外国的服务器你懂得），因此我们可以直接访问<code>http://repo1.maven.org/maven2/archetype-catalog.xml</code>，把这个<code>xml</code>下载下来放到本地的<code>maven</code>目录中，然后在添加一个参数<code>archetypeCatalog=internal</code>就可以了。 <code>next</code> 填写项目名称，<code>finish</code>即可。 建立相应的目录 项目创建完成后，<code>src-main</code>下建立<code>java</code>目录后，是无法在该目录下创建新的包和<code>java</code>类等文件的。在<code>idea</code>中需要对目录进行标注。</p><p><code>Sources</code> 一般用于标注类似 <code>src</code> 这种可编译目录。有时候我们不单单项目的 <code>src</code> 目录要可编译，还有其他一些特别的目录也许我们也要作为可编译的目录，就需要对该目录进行此标注。只有 <code>Sources</code> 这种可编译目录才可以新建 <code>Java</code> 类和包，这一点需要牢记。 <code>Tests</code> 一般用于标注可编译的单元测试目录。在规范的 <code>maven</code> 项目结构中，顶级目录是 <code>src</code>，<code>maven</code> 的 <code>src</code> 我们是不会设置为 <code>Sources</code> 的，而是在其子目录 <code>main</code> 目录下的 <code>java</code> 目录，我们会设置为 <code>Sources</code>。而单元测试的目录是 <code>src - test - java</code>，这里的 <code>java</code> 目录我们就会设置为 <code>Tests</code>，表示该目录是作为可编译的单元测试目录。一般这个和后面几个我们都是在 <code>maven</code> 项目下进行配置的，但是我这里还是会先说说。从这一点我们也可以看出 <code>IntelliJ IDEA</code> 对 <code>maven</code> 项目的支持是比较彻底的。 <code>Resources</code> 一般用于标注资源文件目录。在 <code>maven</code> 项目下，资源目录是单独划分出来的，其目录为：<code>src - main -resources</code>，这里的 <code>resources</code> 目录我们就会设置为 <code>Resources</code>，表示该目录是作为资源目录。资源目录下的文件是会被编译到输出目录下的。 <code>Test Resources</code> 一般用于标注单元测试的资源文件目录。在 <code>maven</code> 项目下，单元测试的资源目录是单独划分出来的，其目录为：<code>src - test -resources</code>，这里的 <code>resources</code> 目录我们就会设置为 <code>Test Resources</code>，表示该目录是作为单元测试的资源目录。资源目录下的文件是会被编译到输出目录下的。 <code>Excluded</code> 一般用于标注排除目录。被排除的目录不会被 <code>IntelliJ IDEA</code> 创建索引，相当于被 <code>IntelliJ IDEA</code> 废弃，该目录下的代码文件是不具备代码检查和智能提示等常规代码功能。 通过上面的介绍，我们知道对于非 <code>maven</code> 项目我们只要会设置 <code>src</code> 即可。 （引用自<code>http://wiki.jikexueyuan.com/project/intellij-idea-tutorial/eclipse-java-web-project-introduce.html</code>） 标注完后，建立如下的目录。</p><p><strong>配置</strong><code>Maven</code><strong>和</strong><code>SpringMVC</code> 配置<code>Maven</code>的<code>pom.xml</code> 完整的配置文件如下。</p><p>&lt;project xmlns=&quot;<a href="http://maven.apache.org/POM/4.0.0" target="_blank" rel="noreferrer">http://maven.apache.org/POM/4.0.0</a>&quot; xmlns:xsi=&quot;<a href="http://www.w3.org/2001/XMLSchema-instance" target="_blank" rel="noreferrer">http://www.w3.org/2001/XMLSchema-instance</a>&quot; xsi:schemaLocation=&quot;<a href="http://maven.apache.org/POM/4.0.0" target="_blank" rel="noreferrer">http://maven.apache.org/POM/4.0.0</a> <a href="http://maven.apache.org/maven-v4_0_0.xsd" target="_blank" rel="noreferrer">http://maven.apache.org/maven-v4_0_0.xsd</a>&quot;&gt; &lt;modelVersion&gt;4.0.0&lt;/modelVersion&gt; &lt;groupId&gt;com.example&lt;/groupId&gt; &lt;artifactId&gt;maven-springmvc&lt;/artifactId&gt; &lt;packaging&gt;war&lt;/packaging&gt; &lt;version&gt;1.0-SNAPSHOT&lt;/version&gt; &lt;name&gt;maven-springmvc Maven Webapp&lt;/name&gt; &lt;url&gt;<a href="http://maven.apache.org" target="_blank" rel="noreferrer">http://maven.apache.org</a>&lt;/url&gt; &lt;!-- 项目依赖</p><ul><li>--&gt;</li><li>&lt;dependencies&gt;</li><li>&lt;!--</li></ul><p>日志包</p><p>--&gt; &lt;dependency&gt; &lt;groupId&gt;junit&lt;/groupId&gt; &lt;artifactId&gt;junit&lt;/artifactId&gt; &lt;version&gt;3.8.1&lt;/version&gt; &lt;scope&gt;test&lt;/scope&gt; &lt;/dependency&gt; &lt;dependency&gt; &lt;groupId&gt;org.slf4j&lt;/groupId&gt; &lt;artifactId&gt;slf4j-log4j12&lt;/artifactId&gt; &lt;version&gt;1.7.21&lt;/version&gt; &lt;/dependency&gt;</p><pre><code>    \\&lt;!--j2ee
</code></pre><p>相关包 <code>servlet</code>、<code>jsp</code>、</p><p>jstl--&gt; &lt;dependency&gt; &lt;groupId&gt;javax.servlet&lt;/groupId&gt; &lt;artifactId&gt;javax.servlet-api&lt;/artifactId&gt; &lt;version&gt;3.1.0&lt;/version&gt; &lt;/dependency&gt; &lt;dependency&gt; &lt;groupId&gt;javax.servlet.jsp&lt;/groupId&gt; &lt;artifactId&gt;jsp-api&lt;/artifactId&gt; &lt;version&gt;2.2&lt;/version&gt; &lt;/dependency&gt; &lt;dependency&gt; &lt;groupId&gt;javax.servlet&lt;/groupId&gt; &lt;artifactId&gt;jstl&lt;/artifactId&gt; &lt;version&gt;1.2&lt;/version&gt; &lt;/dependency&gt;</p><pre><code>    \\&lt;!--mysql
</code></pre><p>驱动包</p><ul><li>--&gt;</li><li>&lt;dependency&gt;</li><li>&lt;groupId&gt;mysql&lt;/groupId&gt;</li><li>&lt;artifactId&gt;mysql-connector-java&lt;/artifactId&gt;</li><li>&lt;version&gt;5.1.35&lt;/version&gt;</li><li>&lt;/dependency&gt;</li><li>&lt;!--spring</li></ul><p>相关包</p><p>--&gt; &lt;dependency&gt; &lt;groupId&gt;org.springframework&lt;/groupId&gt; &lt;artifactId&gt;spring-web&lt;/artifactId&gt; &lt;version&gt;4.3.1.RELEASE&lt;/version&gt; &lt;/dependency&gt; &lt;dependency&gt; &lt;groupId&gt;org.springframework&lt;/groupId&gt; &lt;artifactId&gt;spring-webmvc&lt;/artifactId&gt; &lt;version&gt;4.3.1.RELEASE&lt;/version&gt; &lt;/dependency&gt;</p><pre><code>    \\&lt;!--
</code></pre><p>其他需要的包</p><p>--&gt; &lt;dependency&gt; &lt;groupId&gt;org.apache.commons&lt;/groupId&gt; &lt;artifactId&gt;commons-lang3&lt;/artifactId&gt; &lt;version&gt;3.4&lt;/version&gt; &lt;/dependency&gt; &lt;dependency&gt; &lt;groupId&gt;commons-fileupload&lt;/groupId&gt; &lt;artifactId&gt;commons-fileupload&lt;/artifactId&gt; &lt;version&gt;1.3.1&lt;/version&gt; &lt;/dependency&gt; &lt;/dependencies&gt;</p><pre><code>\\&lt;build\\&gt;
    \\&lt;finalName\\&gt;maven-springmvc\\&lt;/finalName\\&gt;
    \\&lt;resources\\&gt;
        \\&lt;!--
</code></pre><p>表示把<code>java</code>目录下的有关<code>xml</code>文件<code>,properties</code>文件编译<code>/</code>打包的时候放在<code>resource</code>目录下</p><p>--&gt; &lt;resource&gt; &lt;directory&gt;\${basedir}/src/main/java&lt;/directory&gt; &lt;includes&gt; &lt;include&gt;<strong>/*.properties&lt;/include&gt; &lt;include&gt;</strong>/*.xml&lt;/include&gt; &lt;/includes&gt; &lt;/resource&gt; &lt;resource&gt; &lt;directory&gt;\${basedir}/src/main/resources&lt;/directory&gt; &lt;/resource&gt; &lt;/resources&gt; &lt;plugins&gt; &lt;!--servlet 容器 <code>jetty</code>插件</p><p>--&gt; &lt;plugin&gt; &lt;groupId&gt;org.eclipse.jetty&lt;/groupId&gt; &lt;artifactId&gt;jetty-maven-plugin&lt;/artifactId&gt; &lt;version&gt;9.3.10.v20160621&lt;/version&gt; &lt;/plugin&gt; &lt;/plugins&gt; &lt;/build&gt; &lt;/project&gt; 更新完<code>pom.xml</code>文件后，<code>idea</code>应该会自动下载相应的<code>jar</code>包（可能需要<code>vpn</code>），如果没有自动下载的话，可以点击“<code>Reimport All Maven Projects</code>”按钮进行项目的重新载入。如图所示。</p><p><code>jar</code>下载完成后，所有项目所需的依赖就已经添加完成了。</p><p>配置</p><ul><li>web.xml</li><li>maven</li></ul><p>默认生成的<code>web.xml</code>版本是<code>2.3</code>的，所以有些配置节点<code>idea</code>会识别不出来，因此我们重新添加一个<code>3.0</code>的。</p><p>&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt; &lt;web-app xmlns=&quot;<a href="http://java.sun.com/xml/ns/javaee" target="_blank" rel="noreferrer">http://java.sun.com/xml/ns/javaee</a>&quot; xmlns:xsi=&quot;<a href="http://www.w3.org/2001/XMLSchema-instance" target="_blank" rel="noreferrer">http://www.w3.org/2001/XMLSchema-instance</a>&quot; xsi:schemaLocation=&quot;<a href="http://java.sun.com/xml/ns/javaee" target="_blank" rel="noreferrer">http://java.sun.com/xml/ns/javaee</a><a href="http://java.sun.com/xml/ns/javaee/web-app_3_0.xsd" target="_blank" rel="noreferrer">http://java.sun.com/xml/ns/javaee/web-app_3_0.xsd</a>&quot; version=&quot;3.0&quot;&gt; &lt;!--welcome pages--&gt; &lt;welcome-file-list&gt; &lt;welcome-file&gt;index.jsp&lt;/welcome-file&gt; &lt;/welcome-file-list&gt;</p><pre><code>\\&lt;!--
</code></pre><p>配置</p><p>springmvc DispatcherServlet--&gt; &lt;servlet&gt; &lt;servlet-name&gt;springMVC&lt;/servlet-name&gt; &lt;servlet-class&gt;org.springframework.web.servlet.DispatcherServlet&lt;/servlet-class&gt; &lt;init-param&gt; &lt;!--Sources 标注的文件夹下需要新建一个<code>spring</code>文件夹</p><p>--&gt; &lt;param-name&gt;contextConfigLocation&lt;/param-name&gt; &lt;param-value&gt;classpath:spring/spring-mvc.xml&lt;/param-value&gt; &lt;/init-param&gt; &lt;load-on-startup&gt;1&lt;/load-on-startup&gt; &lt;async-supported&gt;true&lt;/async-supported&gt; &lt;/servlet&gt; &lt;servlet-mapping&gt; &lt;servlet-name&gt;springMVC&lt;/servlet-name&gt; &lt;url-pattern&gt;/&lt;/url-pattern&gt; &lt;/servlet-mapping&gt; &lt;/web-app&gt; 接收到的<code>http</code>请求通过<code>DispatcherServlet</code>进行分发。</p><p>配置<code>contextConfigLocation</code>文件</p><p>&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt; &lt;beans xmlns=&quot;<a href="http://www.springframework.org/schema/beans" target="_blank" rel="noreferrer">http://www.springframework.org/schema/beans</a>&quot; xmlns:xsi=&quot;<a href="http://www.w3.org/2001/XMLSchema-instance" target="_blank" rel="noreferrer">http://www.w3.org/2001/XMLSchema-instance</a>&quot; xmlns:context=&quot;<a href="http://www.springframework.org/schema/context" target="_blank" rel="noreferrer">http://www.springframework.org/schema/context</a>&quot; xmlns:mvc=&quot;<a href="http://www.springframework.org/schema/mvc" target="_blank" rel="noreferrer">http://www.springframework.org/schema/mvc</a>&quot; xsi:schemaLocation=&quot;<a href="http://www.springframework.org/schema/beans" target="_blank" rel="noreferrer">http://www.springframework.org/schema/beans</a><a href="http://www.springframework.org/schema/beans/spring-beans-3.2.xsd" target="_blank" rel="noreferrer">http://www.springframework.org/schema/beans/spring-beans-3.2.xsd</a><a href="http://www.springframework.org/schema/context" target="_blank" rel="noreferrer">http://www.springframework.org/schema/context</a><a href="http://www.springframework.org/schema/context/spring-context-3.2.xsd" target="_blank" rel="noreferrer">http://www.springframework.org/schema/context/spring-context-3.2.xsd</a><a href="http://www.springframework.org/schema/mvc" target="_blank" rel="noreferrer">http://www.springframework.org/schema/mvc</a><a href="http://www.springframework.org/schema/mvc/spring-mvc.xsd" target="_blank" rel="noreferrer">http://www.springframework.org/schema/mvc/spring-mvc.xsd</a>&quot;&gt; &lt;!-- 启用<code>spring</code>的一些</p><ul><li>annotation --&gt;</li><li>&lt;context:annotation-config/&gt;</li><li>&lt;!--</li></ul><p>自动扫描该包，使<code>SpringMVC</code>认为包下用了<code>@controller</code>注解的类是控制器</p><p>--&gt; &lt;context:component-scan base-package=&quot;com.zjut.ssm.controller&quot;&gt; &lt;context:include-filter type=&quot;annotation&quot; expression=&quot;org.springframework.stereotype.Controller&quot;/&gt; &lt;/context:component-scan&gt;</p><pre><code>\\&lt;!--HandlerMapping
</code></pre><p>无需配置，<code>springmvc</code>可以默认启动</p><ul><li>--&gt;</li><li>&lt;!--</li></ul><p>静态资源映射</p><ul><li>--&gt;</li><li>&lt;!--</li></ul><p>本项目把静态资源放在了<code>WEB-INF</code>的<code>statics</code>目录下，资源映射如下</p><p>--&gt; &lt;mvc:resources mapping=&quot;/css/<strong>&quot; location=&quot;/WEB-INF/statics/css/&quot;/&gt; &lt;mvc:resources mapping=&quot;/js/</strong>&quot; location=&quot;/WEB-INF/statics/js/&quot;/&gt; &lt;mvc:resources mapping=&quot;/image/**&quot; location=&quot;/WEB-INF/statics/image/&quot;/&gt;</p><pre><code>\\&lt;!--
</code></pre><p>但是项目部署到<code>linux</code>下发现<code>WEB-INF</code>的静态资源会出现无法解析的情况，但是本地<code>tomcat</code>访问正常，因此建议还是直接把静态资源放在<code>webapp</code>的<code>statics</code>下，映射配置如下</p><p>--&gt; &lt;!--&lt;mvc:resources mapping=&quot;/css/<strong>&quot; location=&quot;/statics/css/&quot;/&gt;--&gt; &lt;!--&lt;mvc:resources mapping=&quot;/js/</strong>&quot; location=&quot;/statics/js/&quot;/&gt;--&gt; &lt;!--&lt;mvc:resources mapping=&quot;/image/**&quot; location=&quot;/statics/images/&quot;/&gt;--&gt;</p><pre><code>\\&lt;!--
</code></pre><p>配置注解驱动 可以将<code>request</code>参数与绑定到<code>controller</code>参数上</p><ul><li>--&gt;</li><li>&lt;mvc:annotation-driven/&gt;</li><li>&lt;!--</li></ul><p>对模型视图名称的解析，即在模型视图名称添加前后缀<code>(</code>如果最后一个还是表示文件夹<code>,</code>则最后的斜杠不要漏了<code>)</code> 使用</p><ul><li>JSP--&gt;</li><li>&lt;!--</li></ul><p>默认的视图解析器 在上边的解析错误时使用 <code>(</code>默认使用</p><p>html)- --&gt; &lt;bean id=&quot;defaultViewResolver&quot; class=&quot;org.springframework.web.servlet.view.InternalResourceViewResolver&quot;&gt; &lt;property name=&quot;viewClass&quot; value=&quot;org.springframework.web.servlet.view.JstlView&quot;/&gt; &lt;property name=&quot;prefix&quot; value=&quot;/WEB-INF/views/&quot;/&gt;&lt;!-- 设置<code>JSP</code>文件的目录位置</p><ul><li>--&gt;</li><li>&lt;property name=&quot;suffix&quot; value=&quot;.jsp&quot;/&gt;</li><li>&lt;/bean&gt;</li><li>&lt;!-- springmvc</li></ul><p>文件上传需要配置的节点</p><p>--&gt; &lt;bean id=&quot;multipartResolver&quot; class=&quot;org.springframework.web.multipart.commons.CommonsMultipartResolver&quot;&gt; &lt;property name=&quot;maxUploadSize&quot; value=&quot;20971500&quot;/&gt; &lt;property name=&quot;defaultEncoding&quot; value=&quot;UTF-8&quot;/&gt; &lt;property name=&quot;resolveLazily&quot; value=&quot;true&quot;/&gt; &lt;/bean&gt; &lt;/beans&gt; 配置<code>log4j.properties</code> 日志文件是<code>debug</code>中一个必不可少的工具，因此添加了<code>log4j</code>日志包。配置文件如下。</p><p><code>#</code>配置根<code>Logger</code> 后面是若干个</p><ul><li>Appender</li><li>log4j.rootLogger=DEBUG,A1,R</li><li>#log4j.rootLogger=INFO,A1,R</li><li><h1 id="consoleappender" tabindex="-1">ConsoleAppender <a class="header-anchor" href="#consoleappender" aria-label="Permalink to &quot;ConsoleAppender&quot;">​</a></h1></li></ul><p>输出</p><p>log4j.appender.A1=org.apache.log4j.ConsoleAppender log4j.appender.A1.layout=org.apache.log4j.PatternLayout log4j.appender.A1.layout.ConversionPattern=%-d{yyyy-MM-dd HH:mm:ss,SSS} [%c]-[%p] %m%n</p><h1 id="file" tabindex="-1">File <a class="header-anchor" href="#file" aria-label="Permalink to &quot;File&quot;">​</a></h1><p>输出 一天一个文件<code>,</code>输出路径可以定制<code>,</code>一般在根路径下</p><p>log4j.appender.R=org.apache.log4j.DailyRollingFileAppender log4j.appender.R.File=log.txt log4j.appender.R.MaxFileSize=500KB log4j.appender.R.MaxBackupIndex=10 log4j.appender.R.layout=org.apache.log4j.PatternLayout log4j.appender.R.layout.ConversionPattern=%d{yyyy-MM-dd HH:mm:ss,SSS} [%t] [%c] [%p] - %m%n controller 和<code>view</code>的编写 在<code>controller</code>下新建一个“<code>HomeController</code>”。编写如下代码。</p><p>package com.zjut.ssm.controller;</p><p>import org.slf4j.Logger; import org.slf4j.LoggerFactory; import org.springframework.stereotype.Controller; import org.springframework.web.bind.annotation.RequestMapping;</p><p>/**</p><ul><li>@author Chingyu Mo</li><li>@create 2016-07-23-20:20 */ // 注解标注此类为<code>springmvc</code>的<code>controller</code>，<code>url</code>映射为</li></ul><p>&quot;/home&quot; @Controller @RequestMapping(&quot;/home&quot;) public class HomeController { // 添加一个日志器</p><pre><code>private static final Logger logger = LoggerFactory.getLogger(HomeController.class);

//
</code></pre><p>映射一个</p><p>action @RequestMapping(&quot;/index&quot;) public String index(){ // 输出日志文件</p><pre><code>    logger.info(&quot;the first jsp pages&quot;);
    //
</code></pre><p>返回一个<code>index.jsp</code>这个视图</p><pre><code>    return &quot;index&quot;;
\\}
</code></pre><p>} 在<code>views</code>文件夹下建立一个<code>jsp</code>文件，名为“<code>index.jsp</code>”</p><p>基本的代码编写就完成了。</p><p><code>servlet</code>容器的配置和运行 <code>servlet</code>容器有两种配置方式。</p><p>配置本地的<code>tomcat</code>服务器 配置<code>maven</code>插件 配置本地的<code>tomcat</code>服务器</p><p>根据上图配置<code>tomcat</code>服务器，如果用这种方法，本地需要下载<code>tomcat</code>并配置好环境变量。</p><p>主要有以下几个要点</p><p><code>1.</code>选择本地的<code>tomcat</code>容器。 <code>2.</code>可以选择修改访问路径。 <code>3.On Update action</code> 当我们按 <code>Ctrl + F10</code> 进行容器更新的时候，可以根据我们配置的这个事件内容进行容器更新。其中我选择的 <code>Update classes and resources</code> 事件是最常用的，表示我们在按 <code>Ctrl + F10</code> 进行容器更新的时候，我们触发更新编译的类和资源文件到容器中。 <code>4.</code>默认 <code>Tomcat</code> 的 <code>HTTP</code> 端口是 <code>8080</code>，如果你需要改其端口可以在这里设置。 <code>5.</code>在 <code>Deployment</code> 选项卡中添加了 <code>Artifact</code>。 配置<code>maven</code>插件 <code>maven</code>插件的话有<code>tomcat</code>和<code>jetty</code>，两者都是<code>servlet</code>的容器。我这里配置的是<code>jetty</code>。插件已经在<code>pom.xml</code>中配置完成了。</p><ul><li>&lt;plugins&gt;</li><li>&lt;!--servlet</li></ul><p>容器 <code>jetty</code>插件</p><ul><li>--&gt;</li><li>&lt;plugin&gt;</li><li>&lt;groupId&gt;org.eclipse.jetty&lt;/groupId&gt;</li><li>&lt;artifactId&gt;jetty-maven-plugin&lt;/artifactId&gt;</li><li>&lt;version&gt;9.3.10.v20160621&lt;/version&gt;</li><li>&lt;/plugin&gt;</li><li>&lt;/plugins&gt;</li></ul><p>再在<code>idea</code>中配置<code>jetty</code>。</p><p>运行第一个<code>Spring MVC</code>应用 点击<code>Run</code>，运行。</p><p>以上就是一个简单的<code>Spring MVC</code>应用在<code>idea</code>中的创建方式。 ———————————————— 版权声明：本文为<code>CSDN</code>博主「<code>Jimmy-</code>尹」的原创文章，遵循 <code>CC 4.0 BY-SA</code> 版权协议，转载请附上原文出处链接及本声明。 原文链接：<code>https://blog.csdn.net/jason201710/article/details/101757687</code></p></div>`,1)])])}const m=t(l,[["render",a]]);export{u as __pageData,m as default};
